{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slikk_fact_item as WITH sales AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(sku)) END AS sku, CASE WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-05- SHIRT\' THEN \'4MSN1310-05\' WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-02-SHIRT\' THEN \'4MSN1310-02\' WHEN upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-08-SHIRT\' THEN \'4MSN1310-08\' WHEN upper(sku) LIKE \'4C%\' THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) || \'-\' || SPLIT_PART(sku, \'-\', 3) WHEN POSITION(\'-\' IN sku) > 0 THEN SPLIT_PART(sku, \'-\', 1) || \'-\' || SPLIT_PART(sku, \'-\', 2) ELSE sku END AS sku_group, sp::int AS SP, mrp::int AS MRP, tax::int AS TAX, discount::int AS discount, invoice_id, TO_DATE(order_date, \'DD-MM-YYYY\') AS order_date, total_amount::int AS total_amount, payment_status, total_quantity::int AS total_quantity FROM snitch_db.maplemonk.S3_SLIKK_SALES ), returnss AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(sku)) END AS sku, original_invoice_id AS invoice_id, TO_DATE(create_date, \'DD-MM-YYYY\') AS return_date, MAX(status) AS return_status, SUM(quantity::int) AS return_quantity, MAX(return_reason) AS return_reason, MAX(CASE WHEN LOWER(return_reason) LIKE \'%size%\' THEN \'Size & Fit Issue\' WHEN LOWER(return_reason) LIKE \'%quality%\' THEN \'Quality Issue\' WHEN return_reason = \'Return Reason not found\' THEN \'Return Reason not found\' WHEN return_reason LIKE \'Miscellaneous%\' THEN \'Customer Changed Mined\' WHEN return_reason LIKE \'Order and Shipping Issues%\' THEN \'Order and Shipping Issues\' WHEN return_reason LIKE \'Color and Appearance%\' THEN \'Catalog Issues\' ELSE \'Customer Changed Mined\' END) AS Resaons, MAX(return_invoice_id) AS return_invoice_id FROM snitch_db.maplemonk.S3_SLIKK_RETURNS WHERE status != \'CANCELLED\' GROUP BY sku, original_invoice_id, create_date ), prod_details AS ( SELECT sku_group, product_name, sku_class, category, title, print_design, collar_new, material_new, fit, color, sleeve_type FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) = 1 ) SELECT a.sku, a.sku_group, SPLIT_PART(a.sku, \'-\', 3) AS size, a.sp, a.mrp, a.tax, a.discount, a.invoice_id, a.order_date, a.total_amount, a.payment_status, a.total_quantity, b.return_date, b.return_status, b.return_quantity, b.return_reason, b.Resaons, b.return_invoice_id, c.product_name, c.sku_class, c.category, c.title, c.print_design, c.collar_new, c.material_new, c.fit, c.color, c.sleeve_type FROM sales a LEFT JOIN returnss b ON a.invoice_id = b.invoice_id AND a.sku = b.sku LEFT JOIN prod_details c ON a.sku_group = c.sku_group;",
                    "transaction": true
                }
            ) }}
